import{c as t,ao as e,ah as r,L as p,O as i,I as l,Q as n,aY as s,P as c}from"./chunks/framework.YKVbmyBD.js";const m=JSON.parse('{"title":"更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"web-src/acovia-server/new.md","filePath":"web-src/acovia-server/new.md"}'),u={name:"web-src/acovia-server/new.md"};function g(h,a,d,_,b,k){const o=e("center");return r(),p("div",null,[a[1]||(a[1]=i('<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to “更新日志”">​</a></h1><h2 id="_2026-05-10" tabindex="-1">2026.05.10 <a class="header-anchor" href="#_2026-05-10" aria-label="Permalink to “2026.05.10”">​</a></h2><blockquote><p>本次更新回退了大量内容！</p></blockquote><ul><li><p><strong>公告</strong></p><p>请停止在地图远处建造基地，已建造的区域联系 Fovlin 进行迁移，26.2 版本将会删除存在必要建筑以外的所有区域！以适配新版本生物群系和地形。</p></li><li><p><strong>地址迁移</strong></p><p>服务器地址迁移至 <code>acovia.net</code>。</p></li><li><p><strong>暂时删除异象玩法</strong></p><p>观察到此玩法会带来不好的游戏体验，暂时删除该玩法，已加入的维度不会受影响。</p></li><li><p><strong>客户端整合包更新</strong></p><p>整合包更新至 26.1.2 版本。</p></li><li><p><strong>取消对基岩版的支持</strong></p><p>由于服务器资源有限，将取消对基岩版的支持以节省服务器资源。</p></li><li><p><strong>网站结构变化</strong></p><p>网站分为两个主站点，分为导航页和服务器主页。</p></li></ul><h2 id="_2026-04-19" tabindex="-1">2026.04.19 <a class="header-anchor" href="#_2026-04-19" aria-label="Permalink to “2026.04.19”">​</a></h2><ul><li><p><strong>异象轮替:愁霖</strong></p><p>天空不再蔚蓝，取而代之的是会降下无尽之雨的阴云，已知接触雨水后身上会长出花瓣，身体逐渐停止机能，窒息而亡。</p></li></ul><div class="danger custom-block"><p class="custom-block-title">风险！</p><p>此异象将大幅提高游戏难度，请仔细阅读下列应对措施！</p></div><ul><li><p><strong>异象求生指南：</strong></p><p>已知小镇内的潮涌核心可以净化雨水，在小镇内潮涌核心的庇护下不会受到伤害。</p><p>魔法师<strong>拉诺塔</strong>在得到情报后第一时间制作了便携式潮涌核心-<strong>庇护石</strong>，手持庇护石净化半径 16 格以内的雨水，但由于能量有限，仅制作了4个放在广场的位置供外出人员使用。</p><p>此异象原因未知，仍在全力寻找解决方法。</p></li></ul><blockquote><p>某处的入口貌似被打开了...</p></blockquote><ul><li><p><strong>小型飞行坐骑：</strong></p><p>小镇广场新增三只可飞行的微型乐魂，可供建筑玩家使用，尽量不要使用此坐骑远行，避免丢失。</p></li></ul><h2 id="_2026-04-05" tabindex="-1">2026.04.05 <a class="header-anchor" href="#_2026-04-05" aria-label="Permalink to “2026.04.05”">​</a></h2><p><strong>异像:日蚀</strong></p><p>每三天的白昼会出现日蚀异象，天空、阳光以及环境会呈现诡异的黄色，受到阳光直射将持续损失生命值。</p><ul><li><p><strong>再生之花机制更改</strong></p><p>手持此物品的玩家受到致命伤害会直接回到小镇出生点。</p></li><li><p><strong>创造开发服务器</strong></p><p>喷泉处新增入口可以前往创造开发服务器，用于建筑的构想。</p></li></ul><h2 id="_2026-03-29" tabindex="-1">2026.03.29 <a class="header-anchor" href="#_2026-03-29" aria-label="Permalink to “2026.03.29”">​</a></h2><ul><li><p><strong>新增物品</strong></p><p>回溯卷轴：使用后可以快速回到主城。</p><p>毁_：可以快速挖掘一切可挖掘的方块。</p><p>建筑棒：：可以附魔建筑类特殊附魔方便建造。</p></li><li><p><strong>新增附魔</strong></p><p>Makeway：建筑棒附魔，对土径方块左键可以快速铺设道路。</p></li><li><hr></li></ul><h2 id="_2026-03-15" tabindex="-1">2026.03.15 <a class="header-anchor" href="#_2026-03-15" aria-label="Permalink to “2026.03.15”">​</a></h2><ul><li><p><strong>新增附魔</strong></p><p>Control_AI：魔导棒附魔，用来开关距离你生物最近的 AI。</p><p>Lighting：弓箭附魔，会在箭的落点 3 格范围内寻找目标并召唤雷击。</p></li><li><p><strong>新增物品</strong></p><p>再生之花：受到伤害，立刻将玩家拉回到安全区域。</p></li></ul><h2 id="_2026-02-15" tabindex="-1">2026.02.15 <a class="header-anchor" href="#_2026-02-15" aria-label="Permalink to “2026.02.15”">​</a></h2><ul><li><p><strong>新维度：往日</strong></p><p>往日用来存储过往世界的建筑。玩家的单人生存世界经过柏茯灵的同意后，世界存档内的建筑可被粘贴至往日作为纪念。</p><p>往日内，时间会被锁定在黄昏，设有三个高飞行速度的乐魂，且不会有怪物生成。</p></li></ul><h2 id="_2026-02-11" tabindex="-1">2026.02.11 <a class="header-anchor" href="#_2026-02-11" aria-label="Permalink to “2026.02.11”">​</a></h2><ul><li><p><strong>修复了生物群系混乱问题</strong></p><p>修复了群系混乱问题，地形重置为 1.21.11 版本。</p></li><li><p><strong>官网变更</strong></p><p>&quot;更新日志&quot; 移至 &quot;关于 Acovia 板块&quot; &quot;Acovia 介绍&quot; &quot;加入 Acovia&quot; &quot;服务器规则&quot; 合并为一个页面。 官网主页更名为 &quot;Acovia 知识库&quot;</p></li></ul><h2 id="_2026-02-09" tabindex="-1">2026.02.09 <a class="header-anchor" href="#_2026-02-09" aria-label="Permalink to “2026.02.09”">​</a></h2><ul><li><p><strong>官网配色方案变更</strong></p><p>深色主题强调色改为 #FFAF00,文字颜色添加了少许的暖黄色。</p></li><li><p><strong>新增多种武器</strong></p><p>玩家初次加入服务器可获得武器 &quot;悔_&quot;，为不会损坏的石剑，游戏内日活达到一定天数可找柏茯灵升级为 &quot;悟_&quot; 哦~。</p><p>武器 &quot;悟_&quot; 有多种类型，剑、长矛、重锤、等等。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>所有武器均为纯原版武器，使用更改 nbt 标签实现多种武器增益效果，但在某些地方也进行了削弱，并不会影响原版的游戏平衡性哦！</p></div><p>武器 &quot;悔_&quot;：</p><blockquote><p>那抹美丽而透明的蓝色，即便在无人且漫长的旅途中也闪闪发光...</p></blockquote><p>武器 &quot;悟_&quot;：</p><blockquote><p>原来这一切，不过是始于虚渺的妄想... :::note REoxygen 评价，柏茯灵已经完全沉浸于他自己游玩《旋转音律Rotaeno》的艺术里了。 :::</p></blockquote></li></ul><h2 id="_2026-02-03" tabindex="-1">2026.02.03 <a class="header-anchor" href="#_2026-02-03" aria-label="Permalink to “2026.02.03”">​</a></h2><ul><li><p><strong>新增 /g 以及 /gk 两个命令</strong></p><p><strong>/g</strong> 命令全名：/gyaku</p><p>描述：用于在 主世界/资源世界 两个维度之间切换，保存玩家在当前世界的坐标（包括朝向）并切换至另一个维度，位置为上次在另一个世界保存的坐标处，如果没有在另一个世界保存坐标，会传送至另一个世界的出生点。</p><p>例如：玩家在主世界（-128，64，-128）处使用了命令 /g，由于没有前往资源维度，即没有保存过坐标，会被传送至资源维度的出生点，玩家跑到（256，64，256）并再次使用命令 /g 玩家会被传送至主世界（-128，64，-128）处，再次使用 /g 会被传送到资源维度（256，64，256）处，即手动使用命令离开世界前的位置</p><p><strong>/gk</strong> 命令全名：/gyaku_keep</p><p>描述：用于在 主世界/资源世界 两个维度之间切换，保持玩家当前坐标不变进行传送，两个世界的种子是相同的，即初始地形相同，如果目的地有阻挡则无法传送。</p><p>例如：玩家在（-128，64，-128）处使用了命令 /gk，会被传送至资源维度（-128，64，-128）处，玩家跑到（256，64，256）并再次使用命令 /gk 玩家会被传送至主世界（256，64，256）处，再次使用 /gk 会被传送到资源维度（256，64，256）处。</p></li><li><p><strong>新增新手保护期</strong></p><p>在加入服务器后，玩家在服务器中度过一天，系统日龄+1，不在服务器中的时候不会进行计数，在系统日龄小于 50 时，玩家会有死亡不掉落，但系统日龄超过 50 后，则不会有死亡不掉落效果。</p></li></ul><h2 id="_2026-01-28" tabindex="-1">2026.01.28 <a class="header-anchor" href="#_2026-01-28" aria-label="Permalink to “2026.01.28”">​</a></h2><ul><li>服务器地址迁移为 pure.acovia.net</li><li>向下支持至 1.20.1 版本以上的玩家加入</li></ul><h2 id="_2026-01-15" tabindex="-1">2026.01.15 <a class="header-anchor" href="#_2026-01-15" aria-label="Permalink to “2026.01.15”">​</a></h2><ul><li>原版服重新开张啦～现在用上了双节点部署，只能通过直连进入哦，并且开启了正版验证（基岩版的小可爱们不受影响哟～）💕</li><li>版本温柔地回退到 1.21.11，服务端换上了软乎乎的 Paper 核心，跑得更快更稳啦～🐾</li><li>表层服务器已经悄悄退场，现在只留下温暖又安全的内层服，像小窝一样安心～</li><li>原版服有了专属的交流小群，方便大家和运维贴贴；模组服则交给了超可靠的 REoxygen 照顾，请放心玩耍吧～💫</li></ul><br><br><br>',33)),l("p",null,[l("em",null,[l("strong",null,[n(o,null,{default:s(()=>[...a[0]||(a[0]=[c("--- 由 REoxygen 编写 ---",-1)])]),_:1})])])])])}const f=t(u,[["render",g]]);export{m as __pageData,f as default};
